-- Additive supplier operations. No automatic suspension, message access, or document grants.
create table public.supplier_management_records(business_id uuid primary key references public.businesses,labels text[] not null default '{}',version integer not null default 0,updated_by uuid references public.profiles,updated_at timestamptz not null default now(),check(cardinality(labels)<=10));
create table public.supplier_internal_notes(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses,body text not null check(length(body) between 5 and 3000),created_by uuid not null references public.profiles,created_at timestamptz not null default now(),archived_at timestamptz,archived_by uuid references public.profiles,archive_reason text not null default '');
create index supplier_notes_business_idx on public.supplier_internal_notes(business_id,created_at desc,id);
create table public.supplier_warnings(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses,title text not null check(length(title) between 5 and 160),message text not null check(length(message) between 10 and 3000),corrective_action text not null check(length(corrective_action) between 10 and 2000),severity text not null check(severity in('notice','warning','final_warning')),due_on date not null,status text not null default 'open' check(status in('open','response_submitted','resolved','dismissed')),version integer not null default 1,created_by uuid not null references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index supplier_warning_queue_idx on public.supplier_warnings(business_id,status,due_on,id);
create table public.supplier_warning_events(id uuid primary key default gen_random_uuid(),warning_id uuid not null references public.supplier_warnings,event text not null check(event in('issued','response_submitted','resolved','dismissed')),body text not null check(length(body) between 5 and 3000),actor_id uuid not null references public.profiles,created_at timestamptz not null default now());
create index supplier_warning_events_idx on public.supplier_warning_events(warning_id,created_at,id);
do $$declare t text;begin foreach t in array array['supplier_management_records','supplier_internal_notes','supplier_warnings','supplier_warning_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
create policy management_owner_read on public.supplier_management_records for select to authenticated using(private.is_super_admin());
create policy notes_owner_read on public.supplier_internal_notes for select to authenticated using(private.is_super_admin());
create policy warnings_private_read on public.supplier_warnings for select to authenticated using(private.is_super_admin() or private.owns_business(business_id));
create policy warning_events_private_read on public.supplier_warning_events for select to authenticated using(private.is_super_admin() or exists(select 1 from public.supplier_warnings w where w.id=warning_id and private.owns_business(w.business_id)));
alter table public.notifications drop constraint notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check check(kind in('product_review','verification_review','account_status','staff_access','quotation','quotation_response','onboarding_reminder','supplier_warning','verification_renewal'));
create function private.supplier_management_audit(action text,target uuid,before_value jsonb,after_value jsonb) returns void language sql security definer set search_path='' as $$insert into public.admin_audit_logs(admin_id,action,entity_id,details) values(auth.uid(),action,target,jsonb_build_object('before',before_value,'after',after_value));$$;
create view private.supplier_management_overview as
select b.id,b.owner_id,b.name,b.division,b.district,u.email,u.last_sign_in_at,coalesce(s.status,'active') account_status,private.supplier_verified(b.id) verified,
(length(trim(b.address))>=3 and length(trim(b.description))>=20 and length(trim(b.contact_phone))>=8) profile_complete,
(select count(*) from public.products where business_id=b.id and status='approved') approved_products,
(select count(*) from public.products where business_id=b.id and status='pending') pending_products,
(select count(*) from public.quotation_requests q where q.business_id=b.id and not exists(select 1 from public.quotation_responses r where r.request_id=q.id)) unanswered_quotations,
(select count(*) from public.conversations c where c.business_id=b.id and (select sender_id from public.messages m where m.conversation_id=c.id order by created_at desc,id desc limit 1)=c.buyer_id) unanswered_conversations,
greatest(b.updated_at,(select max(p.updated_at) from public.products p where p.business_id=b.id),(select max(m.created_at) from public.messages m join public.conversations c on c.id=m.conversation_id where c.business_id=b.id and m.sender_id=b.owner_id),(select max(r.created_at) from public.quotation_responses r join public.quotation_requests q on q.id=r.request_id where q.business_id=b.id)) last_activity,
coalesce(g.labels,'{}') labels,coalesce(g.version,0) labels_version,
(select count(*) from public.supplier_warnings w where w.business_id=b.id and w.status in('open','response_submitted')) active_warnings,
(select count(*) from public.supplier_warnings w where w.business_id=b.id and w.status in('open','response_submitted') and w.due_on<private.verification_today()) overdue_warnings
from public.businesses b join auth.users u on u.id=b.owner_id left join public.account_statuses s on s.user_id=b.owner_id left join public.supplier_management_records g on g.business_id=b.id;
revoke all on private.supplier_management_overview from public,anon,authenticated;
create function public.admin_supplier_workspace(target uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin
if not private.is_super_admin() then raise exception 'Super admin required' using errcode='42501';end if;
select to_jsonb(v) into result from private.supplier_management_overview v where v.id=target;if result is null then raise exception 'Supplier not found' using errcode='P0002';end if;return result;end;$$;
create function public.admin_supplier_operations_list(kind text,filters jsonb default '{}',page integer default 1,page_size integer default 25) returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;base text;window_days integer;begin
if not private.is_super_admin() then raise exception 'Super admin required' using errcode='42501';end if;
if page is null or page_size is null or page<1 or page>100000 or page_size<1 or page_size>100 or jsonb_typeof(filters) is distinct from 'object' then raise exception 'Invalid pagination';end if;
if kind='suppliers' then base='select to_jsonb(v)||jsonb_build_object(''created_at'',v.last_activity,''status'',v.account_status) row from private.supplier_management_overview v';
elsif kind='renewals' then
window_days=coalesce(nullif(filters->>'days','')::integer,30);if window_days not in(7,30,60) then raise exception 'Choose 7, 30 or 60 days';end if;
base='select jsonb_build_object(''id'',b.id,''business_id'',b.id,''name'',b.name,''owner_id'',b.owner_id,''account_status'',coalesce(s.status,''active''),''valid_until'',a.valid_until,''days_remaining'',a.valid_until-private.verification_today(),''revision'',a.revision,''latest_status'',(select status from public.verification_applications x where x.business_id=b.id order by revision desc limit 1),''last_reminded_at'',(select max(created_at) from public.notifications n where n.kind=''verification_renewal'' and n.recipient_id=b.owner_id),''created_at'',a.valid_until) row from public.businesses b join public.verification_applications a on a.id=b.verification_application_id left join public.account_statuses s on s.user_id=b.owner_id where a.status in(''approved'',''expired'') and a.valid_until<=private.verification_today()+'||window_days;
elsif kind='notes' then base='select to_jsonb(n)||jsonb_build_object(''author'',p.full_name) row from public.supplier_internal_notes n join public.profiles p on p.id=n.created_by';
elsif kind='warnings' then base='select to_jsonb(w)||jsonb_build_object(''overdue'',w.status in(''open'',''response_submitted'') and w.due_on<private.verification_today(),''events'',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at,e.id) from public.supplier_warning_events e where e.warning_id=w.id),''[]''::jsonb)) row from public.supplier_warnings w';
else raise exception 'Unknown supplier operations list';end if;
execute 'with filtered as materialized(select row from ('||base||') x where (coalesce($1->>''q'','''')='''' or concat_ws('' '',row->>''name'',row->>''email'',row->>''title'') ilike ''%''||left($1->>''q'',200)||''%'') and (coalesce($1->>''business_id'','''')='''' or coalesce(row->>''business_id'',row->>''id'')=$1->>''business_id'') and (coalesce($1->>''status'','''')='''' or row->>''status''=$1->>''status'') and (coalesce($1->>''label'','''')='''' or exists(select 1 from jsonb_array_elements_text(row->''labels'') a where lower(a)=lower($1->>''label'')))),paged as(select row from filtered order by row->>''created_at'' '||case when kind='renewals' then 'asc' else 'desc' end||',row->>''id'' limit $2 offset $3) select jsonb_build_object(''total'',(select count(*) from filtered),''rows'',coalesce((select jsonb_agg(row) from paged),''[]''::jsonb))' into result using filters,page_size,(page-1)*page_size;return result;end;$$;
create function public.admin_supplier_labels(target uuid,expected_version integer,labels text[]) returns jsonb language plpgsql security definer set search_path='' as $$declare current_record public.supplier_management_records;clean text[];begin
if not private.is_super_admin() then raise exception 'Super admin required' using errcode='42501';end if;
if labels is null or cardinality(labels)>10 or exists(select 1 from unnest(labels) x where x is null or length(trim(x)) not between 2 and 40) then raise exception 'Use up to ten labels, 2–40 characters each';end if;
select coalesce(array_agg(value order by lower(value)),'{}') into clean from(select distinct on(lower(trim(x))) trim(x) value from unnest(labels) x order by lower(trim(x)),trim(x)) q;
insert into public.supplier_management_records(business_id) values(target) on conflict do nothing;select * into current_record from public.supplier_management_records where business_id=target for update;
if expected_version is null or current_record.version<>expected_version then raise exception 'Supplier labels changed. Reload before saving.' using errcode='40001';end if;
update public.supplier_management_records set labels=clean,version=version+1,updated_by=auth.uid(),updated_at=now() where business_id=target;
perform private.supplier_management_audit('supplier_management.labels',target,jsonb_build_object('version',current_record.version),jsonb_build_object('version',current_record.version+1,'count',cardinality(clean)));return public.admin_supplier_workspace(target);end;$$;
create function public.admin_supplier_note(target uuid,body text) returns uuid language plpgsql security definer set search_path='' as $$declare nid uuid;begin
if not private.is_super_admin() then raise exception 'Super admin required' using errcode='42501';end if;
if body is null or length(trim(body)) not between 5 and 3000 then raise exception 'Write a note of 5–3000 characters';end if;
insert into public.supplier_internal_notes(business_id,body,created_by) values(target,trim(body),auth.uid()) returning id into nid;
perform private.supplier_management_audit('supplier_management.note_added',target,'{}',jsonb_build_object('note_id',nid));return nid;end;$$;
create function public.admin_supplier_archive_note(target uuid,reason text) returns void language plpgsql security definer set search_path='' as $$declare note public.supplier_internal_notes;begin
if not private.is_super_admin() then raise exception 'Super admin required' using errcode='42501';end if;
if reason is null or length(trim(reason)) not between 5 and 1000 then raise exception 'An archive reason is required';end if;
select * into note from public.supplier_internal_notes where id=target for update;if note.id is null or note.archived_at is not null then raise exception 'Active note not found';end if;
update public.supplier_internal_notes set archived_at=now(),archived_by=auth.uid(),archive_reason=trim(reason) where id=target;
perform private.supplier_management_audit('supplier_management.note_archived',note.business_id,jsonb_build_object('archived',false),jsonb_build_object('archived',true,'note_id',target));end;$$;
create function public.admin_supplier_issue_warning(target uuid,payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare wid uuid;owner uuid;deadline date;begin
if not private.is_super_admin() then raise exception 'Super admin required' using errcode='42501';end if;
if jsonb_typeof(payload) is distinct from 'object' or octet_length(payload::text)>40000 or length(trim(coalesce(payload->>'title',''))) not between 5 and 160 or length(trim(coalesce(payload->>'message',''))) not between 10 and 3000 or length(trim(coalesce(payload->>'corrective_action',''))) not between 10 and 2000 or coalesce(payload->>'severity','') not in('notice','warning','final_warning') then raise exception 'Complete the warning and corrective action';end if;
if coalesce(payload->>'due_on','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Choose a valid correction deadline';end if;deadline=(payload->>'due_on')::date;if deadline is null or deadline<private.verification_today() then raise exception 'Choose today or a future correction deadline';end if;
select owner_id into owner from public.businesses where id=target;if owner is null then raise exception 'Supplier not found';end if;
insert into public.supplier_warnings(business_id,title,message,corrective_action,severity,due_on,created_by) values(target,trim(payload->>'title'),trim(payload->>'message'),trim(payload->>'corrective_action'),payload->>'severity',deadline,auth.uid()) returning id into wid;
insert into public.supplier_warning_events(warning_id,event,body,actor_id) values(wid,'issued',trim(payload->>'message'),auth.uid());
insert into public.notifications(recipient_id,kind,title_en,title_bn,body_en,body_bn,href,entity_id,actor_id) values(owner,'supplier_warning','Supplier action required','সরবরাহকারীর করণীয়','A supplier warning needs your attention. Open your action centre for details.','একটি সতর্কবার্তায় আপনার করণীয় রয়েছে। বিস্তারিত জানতে করণীয় কেন্দ্র খুলুন।','/dashboard/supplier-actions',wid,auth.uid());
perform private.supplier_management_audit('supplier_warning.issued',target,'{}',jsonb_build_object('warning_id',wid,'status','open','due_on',deadline));return wid;end;$$;
create function public.admin_supplier_warning_decide(target uuid,expected_version integer,decision text,reason text) returns void language plpgsql security definer set search_path='' as $$declare warning public.supplier_warnings;begin
if not private.is_super_admin() then raise exception 'Super admin required' using errcode='42501';end if;
if decision is null or decision not in('resolved','dismissed') or reason is null or length(trim(reason)) not between 5 and 3000 then raise exception 'Choose a decision and explain it';end if;
select * into warning from public.supplier_warnings where id=target for update;if warning.id is null then raise exception 'Warning not found';end if;
if expected_version is null or warning.version<>expected_version then raise exception 'Warning changed. Reload before reviewing.' using errcode='40001';end if;
if warning.status not in('open','response_submitted') then raise exception 'Warning is already closed';end if;
update public.supplier_warnings set status=decision,version=version+1,updated_at=now() where id=target;
insert into public.supplier_warning_events(warning_id,event,body,actor_id) values(target,decision,trim(reason),auth.uid());
insert into public.notifications(recipient_id,kind,title_en,title_bn,body_en,body_bn,href,entity_id,actor_id) select owner_id,'supplier_warning','Supplier warning updated','সতর্কবার্তা আপডেট','A decision is available in your supplier action centre.','সরবরাহকারীর করণীয় কেন্দ্রে সিদ্ধান্ত দেখুন।','/dashboard/supplier-actions',target,auth.uid() from public.businesses where id=warning.business_id;
perform private.supplier_management_audit('supplier_warning.'||decision,warning.business_id,jsonb_build_object('status',warning.status,'version',warning.version),jsonb_build_object('status',decision,'version',warning.version+1,'warning_id',target));end;$$;
create function public.supplier_action_list(page integer default 1,page_size integer default 25) returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin
if not private.is_supplier() then raise exception 'Supplier required' using errcode='42501';end if;
if page is null or page_size is null or page<1 or page>100000 or page_size<1 or page_size>100 then raise exception 'Invalid pagination';end if;
with own as materialized(select w.*,(w.status in('open','response_submitted') and w.due_on<private.verification_today()) overdue from public.supplier_warnings w join public.businesses b on b.id=w.business_id where b.owner_id=auth.uid()),paged as(select * from own order by created_at desc,id limit page_size offset (page-1)*page_size)
select jsonb_build_object('total',(select count(*) from own),'rows',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('events',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at,e.id) from public.supplier_warning_events e where e.warning_id=p.id),'[]'))) from paged p),'[]')) into result;return result;end;$$;
create function public.supplier_warning_respond(target uuid,expected_version integer,response text) returns void language plpgsql security definer set search_path='' as $$declare warning public.supplier_warnings;begin
if not private.is_supplier() then raise exception 'Supplier required' using errcode='42501';end if;
select * into warning from public.supplier_warnings where id=target for update;if warning.id is null or not private.owns_business(warning.business_id) then raise exception 'Supplier ownership required' using errcode='42501';end if;
if expected_version is null or warning.version<>expected_version then raise exception 'Warning changed. Reload before responding.' using errcode='40001';end if;
if warning.status not in('open','response_submitted') then raise exception 'Warning is already closed';end if;
if response is null or length(trim(response)) not between 5 and 3000 then raise exception 'Explain the corrections in 5–3000 characters';end if;
perform private.consume_limit('supplier_warning_response',10,60);
update public.supplier_warnings set status='response_submitted',version=version+1,updated_at=now() where id=target;
insert into public.supplier_warning_events(warning_id,event,body,actor_id) values(target,'response_submitted',trim(response),auth.uid());
insert into public.notifications(recipient_id,kind,title_en,title_bn,body_en,body_bn,href,entity_id,actor_id) select user_id,'supplier_warning','Supplier response received','সরবরাহকারীর উত্তর এসেছে','Review a supplier response in supplier management.','সরবরাহকারী ব্যবস্থাপনায় উত্তর পর্যালোচনা করুন।','/admin/supplier-management/'||warning.business_id,target,auth.uid() from public.user_roles where role='super_admin';
perform private.supplier_management_audit('supplier_warning.response_submitted',warning.business_id,jsonb_build_object('status',warning.status,'version',warning.version),jsonb_build_object('status','response_submitted','version',warning.version+1,'warning_id',target));end;$$;
create function public.admin_supplier_renewal_reminder(target uuid) returns void language plpgsql security definer set search_path='' as $$declare business public.businesses;app public.verification_applications;nid uuid;begin
if not private.is_super_admin() then raise exception 'Super admin required' using errcode='42501';end if;
select * into business from public.businesses where id=target for update;if business.id is null then raise exception 'Supplier not found';end if;
select * into app from public.verification_applications where id=business.verification_application_id;
if app.id is null or app.status not in('approved','expired') or app.valid_until>private.verification_today()+60 or app.valid_until is null then raise exception 'No verification renewal is due within 60 days';end if;
if (select status from public.verification_applications where business_id=target order by revision desc limit 1)='submitted' then raise exception 'A replacement application is already awaiting review';end if;
if exists(select 1 from public.notifications where recipient_id=business.owner_id and kind='verification_renewal' and created_at>now()-interval '24 hours') then raise exception 'A renewal reminder was already sent within 24 hours';end if;
insert into public.notifications(recipient_id,kind,title_en,title_bn,body_en,body_bn,href,entity_id,actor_id) values(business.owner_id,'verification_renewal','Verification renewal reminder','যাচাই নবায়নের স্মরণবার্তা','Review your document expiry dates and prepare renewed verification evidence.','নথির মেয়াদ দেখুন এবং নবায়নের জন্য নতুন প্রমাণ প্রস্তুত করুন।','/dashboard/verification',target,auth.uid()) returning id into nid;
perform private.supplier_management_audit('supplier_renewal.reminder',target,'{}',jsonb_build_object('notification_id',nid,'revision',app.revision));end;$$;
-- Internal operational audit events are not exposed to staff.
alter policy audit_read on public.admin_audit_logs using(private.is_admin() and (private.is_super_admin() or (action not like 'homepage_content.%' and action not like 'verification.%' and action not like 'supplier_verifications.%' and action not like 'conversation_monitor.%' and action not like 'supplier_management.%' and action not like 'supplier_warning.%' and action not like 'supplier_renewal.%')));
do $$declare d text;begin d=pg_get_functiondef('public.admin_list(text,jsonb,integer,integer)'::regprocedure);if position('a.action not like ''conversation_monitor.%''' in d)=0 then raise exception 'Existing audit restrictions missing';end if;execute replace(d,'a.action not like ''conversation_monitor.%''','a.action not like ''conversation_monitor.%'' and a.action not like ''supplier_management.%'' and a.action not like ''supplier_warning.%'' and a.action not like ''supplier_renewal.%''');end;$$;
do $$declare f record;begin for f in select p.oid::regprocedure signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private') and p.proname in('supplier_management_audit','admin_supplier_workspace','admin_supplier_operations_list','admin_supplier_labels','admin_supplier_note','admin_supplier_archive_note','admin_supplier_issue_warning','admin_supplier_warning_decide','supplier_action_list','supplier_warning_respond','admin_supplier_renewal_reminder') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);if f.nspname='public' then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end;$$;
